mapper.select:
select t.task_id taskId, t.task_name taskName, p.park_name parkName, d.device_name deviceName, m.model_name modelName, t.crop_type cropType, t.schedule_type scheduleType, t.fixed_times fixedTimes, t.interval_minutes intervalMinutes, t.task_status taskStatus, t.run_state runState, t.last_run_time lastRunTime, t.next_run_time nextRunTime, t.last_run_status lastRunStatus from sxz_disease_auto_task t left join park p on p.park_id = t.park_id left join iot_device d on d.device_id = t.device_id left join xwq_ai_model m on m.model_id = t.model_id
t.del_flag = '0' and t.task_name like concat('%', #{taskName}, '%') and t.park_id = #{parkId} and t.device_id = #{deviceId} and t.task_status = #{taskStatus} and t.run_state = #{runState}
order by t.create_time desc, t.task_id desc

select r.run_id runId, r.task_id taskId, r.task_name taskName,
       r.trigger_type triggerType, r.run_status runStatus,
       r.start_time startTime, r.end_time endTime,
       r.source_count sourceCount, r.recognize_count recognizeCount,
       r.success_count successCount, r.fail_count failCount,
       r.skip_count skipCount, r.error_message errorMessage
from sxz_disease_auto_task_run r

    r.task_id = #{taskId}
    and r.task_name like concat('%', #{taskName}, '%')
    and r.trigger_type = #{triggerType}
    and r.run_status = #{runStatus}
    and r.start_time >= #{beginTime}
    and r.start_time <= #{endTime}

order by r.start_time desc, r.run_id desc

select i.item_id itemId, t.task_name taskName, i.run_id runId, i.source_image_id sourceImageId, i.ai_image_id aiImageId, i.record_id recordId, i.disease_id diseaseId, d.disease_name diseaseName, d.disease_confidence confidence, i.item_status itemStatus, i.attempt_count attemptCount, i.start_time startTime, i.finish_time finishTime, i.error_message errorMessage, coalesce(img.image_url, src.url) imageUrl, coalesce(d.disease_result_img_url, img.image_result_url) resultImageUrl from sxz_disease_auto_task_item i join sxz_disease_auto_task t on t.task_id = i.task_id left join image_record src on src.id = i.source_image_id left join xwq_ai_image img on img.image_id = i.ai_image_id left join xwq_ai_disease d on d.disease_id = i.disease_id
i.task_id = #{taskId} and i.run_id = #{runId} and t.task_name like concat('%', #{taskName}, '%') and i.item_status = #{itemStatus} and d.disease_name like concat('%', #{diseaseName}, '%') and i.create_time >= #{beginTime} and i.create_time <= #{endTime}
order by i.create_time desc, i.item_id desc
